 h.windows[0].webContents.destroyed=true;const requests=h.outbound.length,notices=h.notifications.length;interval.fn();assert.equal(h.outbound.length,requests);h.powerMonitor.emit('lock-screen');h.reply(h.outbound.at(-1),{});assert.equal(h.notifications.length,notices);h.windows[0].webContents.destroyed=false;
