test('TP041 visible app version is read-only local metadata with exact sender, frame and origin checks',async t=>{
 const h=mainHarness({version:'0.2.13'});t.after(h.cleanup);await h.ready();assert.equal(await h.version(),'0.2.13');assert.equal(h.outbound.length,0);const good=h.event();for(const bad of [{sender:{},senderFrame:good.senderFrame},{sender:good.sender,senderFrame:{url:'wallet://app/'}},{sender:good.sender,senderFrame:null}])await assert.rejects(h.version(bad),/Untrusted frame/);for(const url of ['https://evil.test/','wallet://app.evil/','file:///tmp/app']){good.senderFrame.url=url;await assert.rejects(h.version(good),/Untrusted frame/)}good.senderFrame.url='wallet://app/';h.windows[0].emit('closed');await assert.rejects(h.version(good),/Untrusted frame/);
 const r=await rendererHarness({version:'0.2.13+public-test'});t.after(r.close);assert.equal(r.$('version').textContent,'Version 0.2.13+public-test');r.notifyLock();assert.equal(r.$('version').textContent,'Version 0.2.13+public-test');const failed=await rendererHarness({versionFailure:true});t.after(failed.close);assert.equal(failed.$('version').textContent,'Version unavailable');const hostile=await rendererHarness({version:'<img src=x onerror=alert(1)>'});t.after(hostile.close);assert.equal(hostile.$('version').children.length,0)
});

test('TP043 native prompt activity renews only its correlated six-minute deadline and never resolves or creates a request',async t=>{
 const bodies={exchangeConnect:{endpoint:'https://api.bybit.com'},exchangeDisconnect:{},exchangeDeposit:{accountId:'a',assetId:'n:native',amount:'1'},exchangeSwap:{accountId:'a',assetId:'n:native',side:'Sell',amount:'1',slippage:'0.5'},exchangeWithdraw:{accountId:'a',assetId:'n:native',amount:'1'},create:{words:12},import:{words:12},unlock:{},confirmRecovery:{},password:{},receive:{accountId:'a'},copyReceive:{accountId:'a'},saveQR:{accountId:'a'},scanQR:{},configure:{network:'n'},associate:{accountId:'a',address:'named'},discovery:{accountId:'a',birthday:0,gap:1,limit:1,blockBudget:0},discoverAccounts:{start:0,end:1},send:{id:'original'}};
 for(const [method,body] of Object.entries(bodies)){const h=mainHarness();t.after(h.cleanup);await h.ready();let settled=false;const p=h.call(method,body).then(value=>{settled=true;return value});const request=h.outbound[0],initial=[...h.timers.values()][0];assert.equal(initial.ms,360000);h.reply(request,{}, {method:'activity'});assert.equal(h.timers.size,1);const renewed=[...h.timers.values()][0];assert.notEqual(renewed,initial);assert.equal(renewed.ms,360000);initial.fn();await tick();assert.equal(settled,false);assert.equal(h.stdin.destroyed,false);h.reply(request,{}, {method:'activity'});h.clock(11_001);h.reply(request,{}, {method:'activity'});h.intervals.values().next().value.fn();await tick();assert.equal(settled,false);assert.equal(h.outbound.length,1);assert.equal(h.notifications.length,0);h.reply(request,{publicResult:true});assert.deepEqual(plain(await p),{publicResult:true});assert.equal(h.timers.size,0);renewed.fn();await tick();assert.equal(h.stdin.destroyed,false)}
});

test('TP043 malformed, non-native, stale and excessive native activity fail closed without exposing input values',async t=>{
 const mutations=[r=>({...r,body:null}),r=>({...r,body:[]}),r=>({...r,body:'input must not exist'}),r=>({...r,body:1}),r=>({...r,body:{key:'CANARY-native-input'}}),r=>({...r,error:''}),r=>({...r,error:'CANARY-native-error'}),r=>({...r,id:'stale-id'}),r=>({...r,session:'b'.repeat(32)}),r=>({...r,version:2})];
 for(const mutation of mutations){const h=mainHarness();t.after(h.cleanup);await h.ready();const promise=h.call('unlock');const rejected=assert.rejects(promise,/REQUEST_FAILED_STATE_UNKNOWN/);h.stdout.write(framed(mutation({...h.outbound[0],method:'activity',body:{}})));await rejected;assert.equal(h.timers.size,0);assert.equal(h.stdin.destroyed,true);assert.ok(h.notifications.every(args=>JSON.stringify(args)==='["wallet:locked"]'))}
 {const h=mainHarness();t.after(h.cleanup);await h.ready();const promise=h.call('status');const rejected=assert.rejects(promise,/REQUEST_FAILED_STATE_UNKNOWN/);h.reply(h.outbound[0],{}, {method:'activity'});await rejected}
 {const h=mainHarness();t.after(h.cleanup);await h.ready();const original=h.call('unlock'),request=h.outbound[0];h.reply(request,{});await original;const next=h.call('unlock');const rejected=assert.rejects(next,/REQUEST_FAILED_STATE_UNKNOWN/);h.reply(request,{}, {method:'activity'});await rejected}
 {const h=mainHarness();t.after(h.cleanup);await h.ready();const promise=h.call('unlock');const rejected=assert.rejects(promise,/REQUEST_FAILED_STATE_UNKNOWN/);for(let i=0;i<65;i++)h.reply(h.outbound[0],{}, {method:'activity'});await rejected;assert.equal(h.outbound.length,1);assert.equal(h.timers.size,0)}
});

