 assert.equal(h.$('onboardcreate').disabled,false);assert.equal(h.$('onboarding').hidden,true);assert.equal(h.$('walletcontent').hidden,false);assert.equal(h.$('emptyactions').hidden,true);assert.equal(h.$('accountgroups').children.length,1);assert.equal(h.$('accountgroups').querySelector('h2').textContent,'Main account');assert.match(h.$('accountgroups').textContent,/Derivation index 0/);assert.equal(h.$('accountgroups').querySelectorAll('.walletrow').length,ids.length);assert.deepEqual([...h.$('accountgroups').querySelectorAll('.openwallet')].map(node=>node.textContent),networks.map(network=>network.name));assert.equal(h.$('account').options.length,ids.length);assert.equal(h.calls.filter(call=>call.method==='create').length,1);assert.ok(!h.calls.some(call=>call.method==='addAccount'||call.method==='send'));
