 assert.equal(h.$('recoverycallout').hidden,false);assert.match(h.$('recoverystatus').textContent,/setup required/);h.handlers.confirmRecovery=()=>{h.setState({accounts,recoveryConfirmed:true});return {}};const before=h.calls.length;await h.invoke('recoverycontinue');assert.deepEqual(h.calls[before],{method:'confirmRecovery',body:{}});assert.equal(h.$('recoverycallout').hidden,true);assert.equal(h.$('recoverystatus').textContent,'Recovery phrase recorded');
 h.notifyLock();assert.equal(h.$('accountgroups').children.length,0);assert.equal(h.$('walletcontent').hidden,true);assert.equal(h.$('recoverycallout').hidden,true);assert.equal(h.$('onboardunlock').hidden,false);assert.equal(h.$('onboardcreate').hidden,true);
