test('TP031 unavailable or inconsistent storage never authorizes onboarding creation or restoration; retry requires confirmed absence',async t=>{
 for(const state of [{walletExists:true,vaultState:'unavailable'},{walletExists:false,vaultState:'unavailable'},{walletExists:true,vaultState:'missing'},{walletExists:false,vaultState:'present'},{walletExists:undefined,vaultState:undefined},{walletExists:false,vaultState:'missing',locked:false}]){
  const h=await rendererHarness({state:{locked:true,...state}});t.after(h.close);
  if(state.vaultState==='missing'&&state.walletExists===false){assert.equal(h.$('onboardcreate').hidden,false);assert.equal(h.$('walletcontent').hidden,true);continue}
  assert.equal(h.$('onboardtitle').textContent,'Wallet storage unavailable');assert.equal(h.$('onboardcreate').hidden,true);assert.equal(h.$('emptyactions').hidden,true);assert.equal(h.$('onboardunlock').hidden,true);assert.equal(h.$('onboardretry').hidden,false);assert.deepEqual(h.calls,[{method:'accounts',body:{}}]);
  h.setState({locked:true,walletExists:false,vaultState:'missing',accounts:[]});await h.invoke('onboardretry');assert.equal(h.$('onboardcreate').hidden,false);assert.equal(h.$('onboardretry').hidden,true);assert.equal(h.calls.filter(call=>call.method==='create'||call.method==='import').length,0);
 }
});

