const safeOperationCodes=['PASSWORD_POLICY','INPUT_TOO_LONG','PASSWORD_MISMATCH','INVALID_MNEMONIC','REQUEST_CANCELLED','REQUEST_FAILED_STATE_UNKNOWN'];

test('TP041 operation failures resolve the IPC handler with only allowlisted value-free codes',async t=>{
 const h=mainHarness();t.after(h.cleanup);await h.ready();
 for(const code of [...safeOperationCodes,'CANARY-private-path-or-input','', '__proto__']){
  const pending=h.rawCall('confirmRecovery');h.reply(h.outbound.at(-1),{secret:'CANARY-never-forwarded'},{error:code});
  assert.deepEqual(plain(await pending),{ok:false,error:safeOperationCodes.includes(code)?code:'REQUEST_FAILED_STATE_UNKNOWN'});
  assert.equal(h.stdin.destroyed,false);assert.equal(h.notifications.length,0);assert.equal(h.timers.size,0);
 }
 const pending=h.rawCall('accounts');h.reply(h.outbound.at(-1),{accounts:[]});assert.deepEqual(plain(await pending),{ok:true,body:{accounts:[]}});
 h.app.emit('before-quit');assert.deepEqual(plain(await h.rawCall('confirmRecovery')),{ok:false,error:'REQUEST_FAILED_STATE_UNKNOWN'});
});

test('TP041 preload strictly unwraps operation results and drops raw handler, protocol and error details',async()=>{
 let exposed,response;let invokeFailure=false;
 const electron={contextBridge:{exposeInMainWorld(_name,api){exposed=api}},ipcRenderer:{invoke:async()=>{if(invokeFailure)throw Error('CANARY-handler-rejection');return response}}};
 const context=vm.createContext({exports:{},window:{addEventListener(){}},require:name=>{assert.equal(name,'electron');return electron}});
 new vm.Script(fs.readFileSync(path.join(root,'app/preload.js'),'utf8'),{filename:path.join(root,'app/preload.js')}).runInContext(context);
 for(const body of [null,0,false,[],{accounts:[]}]){response={ok:true,body};assert.deepEqual(plain(await exposed.confirmRecovery()),body)}
 for(const code of safeOperationCodes){response={ok:false,error:code};await assert.rejects(exposed.confirmRecovery(),error=>{assert.equal(error.message,code);return true})}
 for(const value of [null,undefined,0,[],{},'CANARY-value',{ok:true},{ok:true,body:{},extra:'CANARY-value'},{ok:false,error:'CANARY-input'},{ok:false,error:1},{ok:false,error:'PASSWORD_POLICY',extra:'CANARY-path'},{ok:'true',body:{}},Object.assign(Object.create({ok:true}),{body:{},extra:true}),Object.assign(Object.create({ok:false}),{error:'PASSWORD_POLICY',extra:true})]){
  response=value;await assert.rejects(exposed.confirmRecovery(),error=>{assert.equal(error.message,'REQUEST_FAILED_STATE_UNKNOWN');return true});
 }
 invokeFailure=true;await assert.rejects(exposed.confirmRecovery(),error=>{assert.equal(error.message,'REQUEST_FAILED_STATE_UNKNOWN');return true});
});

