 const pending=deferred();h.handlers.reconcile=()=>pending.promise;const work=h.$('operations').querySelector('button').onclick();await tick();h.$('journalasset').value='base:zen';h.$('journalasset').dispatchEvent(new h.dom.window.Event('change'));assert.equal(h.$('journalresult').textContent,'No journal action requested.');pending.resolve({detail:'STALE-ETH-RECONCILE'});await work;assert.ok(!h.$('journalresult').textContent.includes('STALE'));assert.equal(h.$('preview').textContent,preview);assert.equal(h.$('send').disabled,true);assert.equal(h.$('asset').value,'base:native');
