test('TP043 overview balance scheduling pauses for native address actions until success, cancellation, failure or lock settles',async t=>{
 for(const outcome of ['success','cancel','failure','lock']){
  const accounts=[{id:'a',network:'testnet',index:0,address:'PUBLIC-A'},{id:'b',network:'testnet',index:0,address:'PUBLIC-B'}],balance=deferred(),native=deferred();
  const h=await rendererHarness({accounts,readBalances:()=>balance.promise});t.after(h.close);h.handlers.copyReceive=()=>native.promise;
  const work=h.$('accountgroups').querySelector('[data-account-id="a"] .copyaddress').onclick();await tick();assert.equal(h.calls.filter(c=>c.method==='copyReceive').length,1);
  h.handlers.balances=()=>[{asset:'testnet:native',atomic:'2',state:'spendable',at:'SECOND-BLOCK'}];balance.resolve([{asset:'testnet:native',atomic:'1',state:'spendable',at:'FIRST-BLOCK'}]);await delay();await delay();assert.equal(h.calls.filter(c=>c.method==='balances').length,1,outcome);
  if(outcome==='lock')h.notifyLock();if(['cancel','failure'].includes(outcome))native.reject(Error(outcome==='cancel'?'REQUEST_CANCELLED':'REQUEST_FAILED_STATE_UNKNOWN'));else native.resolve({});await work;
  if(outcome==='lock'){await delay();assert.equal(h.calls.filter(c=>c.method==='balances').length,1);assertRendererLocked(h)}else{await until(()=>h.calls.filter(c=>c.method==='balances').length===2);assert.match(rowBalance(h,'b').textContent,/2 ETH.*SECOND-BLOCK/)}
  assert.ok(!h.calls.some(c=>['prepare','max','send','retry','cancelPrepared'].includes(c.method)));
 }
});

