// These transport tests use disposable credentials and Electron API doubles.
// Actual Chromium sandbox/display evidence belongs to the packaged driver.
const syntheticPrompt={id:'d'.repeat(32),kind:'input',title:'Unlock wallet',labels:['App password']};
function promptSender(h,index=h.windows.length-1){const w=h.windows[index];return {sender:w.webContents,senderFrame:w.webContents.mainFrame}}
function invokePrompt(h,action,body,sender=promptSender(h)){return Promise.resolve().then(()=>h.ipcMain.handlers.get('wallet:prompt:'+action)(sender,body))}
async function emitPrompt(h,request,prompt=syntheticPrompt){h.reply(request,prompt,{method:'prompt'});await tick();await tick();return h.windows.at(-1)}
test('TP033 isolated Electron prompt receives secrets once, returns bound input and clears its entire session',async t=>{
 const h=mainHarness();t.after(h.cleanup);await h.ready();const operation=h.call('unlock');const original=h.outbound[0];const modal=await emitPrompt(h,original);
 assert.equal(h.windows.length,2);assert.equal(modal.url,'wallet://prompt/');assert.equal(modal.config.parent,h.windows[0]);assert.equal(modal.config.modal,true);assert.equal(modal.shown,true);assert.equal(modal.menu,null);let titlePrevented=false;modal.emit('page-title-updated',{preventDefault(){titlePrevented=true}},'Untrusted document title');assert.equal(titlePrevented,true);assert.equal(modal.config.title,'LocalWallet — Unlock wallet');assert.equal(modal.title,'LocalWallet — Unlock wallet');assert.equal(modal.titleAtShow,'LocalWallet — Unlock wallet');assert.equal(modal.setTitleCalled,true);assert.equal(modal.config.webPreferences.preload,path.join(root,'app/prompt-preload.js'));assert.notEqual(modal.config.webPreferences.partition,'wallet-local');
 for(const key of ['contextIsolation','sandbox','webSecurity'])assert.equal(modal.config.webPreferences[key],true);for(const key of ['nodeIntegration','allowRunningInsecureContent','webviewTag','devTools'])assert.equal(modal.config.webPreferences[key],false);
 const publicEvent=h.event();await assert.rejects(invokePrompt(h,'get',undefined,publicEvent),/Prompt unavailable/);await assert.rejects(h.call('status',{},promptSender(h)),/Untrusted frame/);await assert.rejects(h.version(promptSender(h)),/Untrusted frame/);
 const received=await invokePrompt(h,'get');assert.deepEqual(plain(received),syntheticPrompt);await assert.rejects(invokePrompt(h,'get'),/Prompt unavailable/);
 const disposable='SYNTHETIC-PROMPT-ONLY-CREDENTIAL';await invokePrompt(h,'reply',{promptId:syntheticPrompt.id,accepted:true,values:[disposable]});assert.equal(modal.isDestroyed(),true);assert.equal(h.partitions.get(modal.config.webPreferences.partition).cleared,true);assert.equal(received.title,'');assert.equal(received.labels,undefined);
 assert.deepEqual(h.outbound[1],{version:1,id:original.id,session:original.session,method:'promptReply',body:{promptId:syntheticPrompt.id,accepted:true,values:[disposable]}});assert.equal(h.outbound.length,2);h.reply(original,{locked:false});assert.deepEqual(plain(await operation),{locked:false});assert.ok(h.notifications.every(value=>!JSON.stringify(value).includes(disposable)));await assert.rejects(invokePrompt(h,'reply',{promptId:syntheticPrompt.id,accepted:true,values:[disposable]}),/Prompt unavailable/);
});
test('TP041 prompt assets and permissions are scoped to a distinct ephemeral origin',async t=>{
 const h=mainHarness();t.after(h.cleanup);await h.ready();const op=h.call('unlock');const original=h.outbound[0];const modal=await emitPrompt(h,original);const ses=h.partitions.get(modal.config.webPreferences.partition);
 for(const route of ['/','/prompt.js','/prompt.css'])assert.equal((await ses.resource({url:'wallet://prompt'+route})).status,200);
 for(const url of ['wallet://app/','wallet://prompt/renderer.js','wallet://prompt/prompt.js?x=1','wallet://prompt/#x','wallet://evil/'])assert.equal((await ses.resource({url})).status,403);
 for(const url of ['https://evil.test/','file:///etc/passwd','wallet://app/','data:text/html,x']){let result;ses.beforeRequest({url},value=>result=value);assert.equal(result.cancel,true)}
 for(const url of ['wallet://prompt/','data:image/png;base64,iVBORw0KGgo=']){let result;ses.beforeRequest({url},value=>result=value);assert.equal(result.cancel,false)}
 let allowed;ses.permissionRequest({},'clipboard-read',value=>allowed=value);assert.equal(allowed,false);assert.equal(ses.permissionCheck(),false);let prevented=false;ses.emit('will-download',{preventDefault(){prevented=true}});assert.equal(prevented,true);prevented=false;modal.webContents.emit('will-attach-webview',{preventDefault(){prevented=true}});assert.equal(prevented,true);assert.deepEqual(plain(modal.webContents.openWindow()),{action:'deny'});
 await assert.rejects(invokePrompt(h,'get',undefined,{sender:modal.webContents,senderFrame:{url:'wallet://prompt/'}}),/Prompt unavailable/);modal.webContents.mainFrame.url='wallet://prompt/?x=1';await assert.rejects(invokePrompt(h,'get'),/Prompt unavailable/);modal.webContents.mainFrame.url='wallet://prompt/';modal.destroy();assert.equal(h.outbound.at(-1).body.accepted,false);h.reply(original,null,{error:'REQUEST_CANCELLED'});await assert.rejects(op,/REQUEST_CANCELLED/);
});
