test('TP043 prompt navigation, crash, OS lock, close, timeout and core EOF release secrets and cancel approvals',async t=>{
 for(const scenario of ['navigate','crash','lock','close','timeout','eof','finish']){
  const h=mainHarness({storageFailure:true});t.after(h.cleanup);await h.ready();const op=h.call('create',{words:12});const rejected=scenario==='finish'?undefined:assert.rejects(op,/REQUEST_/);const original=h.outbound[0];const modal=await emitPrompt(h,original,{id:syntheticPrompt.id,kind:'recovery',title:'Record recovery phrase',phrase:Array(12).fill('abandon').join(' ')});const received=await invokePrompt(h,'get');assert.ok(received.phrase);
  if(scenario==='navigate'){let prevented=false;modal.webContents.emit('will-navigate',{preventDefault(){prevented=true}});assert.equal(prevented,true)}
  if(scenario==='crash')modal.webContents.emit('render-process-gone');
  if(scenario==='lock')h.powerMonitor.emit('lock-screen');
  if(scenario==='close')modal.destroy();
  if(scenario==='timeout'){const timer=h.timers.values().next().value;timer.fn()}
  if(scenario==='eof')h.stdout.end();
  if(scenario==='finish'){h.reply(original,{recoveryConfirmed:true});assert.deepEqual(plain(await op),{recoveryConfirmed:true})}
  await tick();assert.equal(modal.isDestroyed(),true);assert.equal(received.phrase,undefined);assert.equal(h.partitions.get(modal.config.webPreferences.partition).cleared,true);
  if(!['eof','finish'].includes(scenario)){assert.deepEqual(h.outbound[1].body,{promptId:syntheticPrompt.id,accepted:false});if(scenario!=='close'){assert.equal(h.outbound[2].method,'lock');h.reply(h.outbound[2],{})}if(scenario!=='timeout')h.reply(original,null,{error:'REQUEST_CANCELLED'})}
  if(rejected)await rejected;
  await assert.rejects(invokePrompt(h,'get'),/Prompt unavailable/);h.ipcMain.emit('wallet:prompt:activity',promptSender(h));
 }
});
