 const h=mainHarness();t.after(h.cleanup);await h.ready();const op=h.call('unlock');const original=h.outbound[0];const oldTimer=h.timers.values().next().value;const modal=await emitPrompt(h,original);const wc=modal.webContents;
 h.ipcMain.emit('wallet:prompt:activity',h.event());assert.equal(h.outbound.length,1);wc.emit('before-input-event',{});assert.equal(h.outbound.at(-1).method,'activity');h.reply(h.outbound.at(-1),{});oldTimer.fn();assert.equal(modal.isDestroyed(),false);h.ipcMain.emit('wallet:prompt:activity',promptSender(h));assert.equal(h.outbound.length,2);
 h.clock(12_001);h.ipcMain.emit('wallet:prompt:activity',promptSender(h));assert.equal(h.outbound.length,3);h.reply(h.outbound.at(-1),{});let prevented=false;wc.emit('before-input-event',{preventDefault(){prevented=true}},{control:true,key:'r'});assert.equal(prevented,true);assert.equal(h.outbound.length,3);wc.emit('before-input-event',{}, {meta:false,control:false,key:'a'});assert.equal(h.outbound.length,3);
