test('TP043 account paging rejects changed, duplicated, truncated and excessive generations without a partial portfolio',async t=>{
 const base={locked:false,walletExists:true,vaultState:'present',recoveryConfirmed:true,revision:'7',totalAccounts:2};const a={id:'a',network:'testnet',index:0,address:'PUBLIC-A'},b={id:'b',network:'testnet',index:1,address:'PUBLIC-B'},token='ab'.repeat(16);
 for(const scenario of ['generation','total','locked','missing-array','duplicate','truncated','repeated-cursor','url-cursor','initial-count','initial-total','initial-revision','record-bound','byte-bound','request-error']){
  const h=await rendererHarness({readAccounts:body=>{
   if(!body.cursor){const first={...base,accounts:[a],accountsCursor:token};if(scenario==='initial-count')return {...first,accountsCursor:''};if(scenario==='initial-total')return {...first,totalAccounts:-1};if(scenario==='initial-revision')return {...first,revision:''};if(scenario==='url-cursor')return {...first,accountsCursor:'https://evil.invalid/'};return first}
   if(scenario==='request-error')throw Error('CANARY-PRIVATE-SIGNER-ERROR');
   const page={...base,accounts:[b],accountsCursor:''};
   if(scenario==='generation')return {...page,revision:'8'};if(scenario==='total')return {...page,totalAccounts:3};if(scenario==='locked')return {...page,locked:true};if(scenario==='missing-array')return {...page,accounts:null};if(scenario==='duplicate')return {...page,accounts:[a]};if(scenario==='truncated')return {...page,accounts:[]};if(scenario==='repeated-cursor')return {...page,accountsCursor:token};if(scenario==='record-bound')return {...page,accounts:Array.from({length:10000},()=>b)};if(scenario==='byte-bound')return {...page,accounts:[{...b,address:'x'.repeat(16777217)}]};return page;
  }});t.after(h.close);assert.equal(h.$('account').options.length,0,scenario);assert.equal(h.$('onboardtitle').textContent,'Wallet storage unavailable',scenario);assert.equal(h.$('onboardcreate').hidden,true,scenario);assert.ok(!h.dom.window.document.body.textContent.includes('PUBLIC-A'),scenario);assert.ok(!h.dom.window.document.body.textContent.includes('CANARY'),scenario);
 }
});

