test('Exchange public schemas reject credentials, arbitrary endpoints, side confusion and inexact numeric amounts',()=>{
 for(const validSlippage of ['0.01','0.5','0.50','1','1.0','1.00'])validate('exchangeSwap',{accountId:'a',assetId:'n:native',side:'Sell',amount:'1',slippage:validSlippage});for(const endpoint of ['https://api.bybit.com','https://api.bybit.ae','https://api.bytick.com','https://api.bybit.tr','https://api.bybit.kz','https://api.bybitgeorgia.ge','https://api.bybit.eu','https://api.bybit.id','https://api.manepa.jp','https://api.spark-fintech.com'])validate('exchangeConnect',{endpoint});for(const endpoint of ['http://api.bybit.com','https://api.bybit.com/','https://api.bybit.com.evil.test','https://api.bybit.com@evil.test','https://api.bybit.com?key=x','https://api.bybit.com:443','https://api-testnet.bybit.com',3,null])assert.throws(()=>validate('exchangeConnect',{endpoint}));
 for(const method of ['exchangeStatus','exchangeConnect','exchangeDisconnect','exchangeQuote','exchangeDeposit','exchangeSwap','exchangeWithdraw','exchangeReconcile'])for(const forbidden of ['apiKey','apiSecret','password','endpointURL','address','symbol','chain','rawBody'])assert.throws(()=>validate(method,{[forbidden]:'never-accepted'}));
 for(const amount of ['1','0.000000000000000001','9007199254740993.123456789012345678']){validate('exchangeDeposit',{accountId:'a',assetId:'n:native',amount});validate('exchangeWithdraw',{accountId:'a',assetId:'n:native',amount});for(const side of ['Buy','Sell'])validate('exchangeSwap',{accountId:'a',assetId:'n:native',side,amount,slippage:'0.5'})}
 for(const amount of [0,1,1.5,NaN,Infinity,null,'0','0.000','-1','+1','1e3','01',' 1','1 ','1.','1,1','1\n','1'.repeat(129)]){assert.throws(()=>validate('exchangeDeposit',{accountId:'a',assetId:'n:native',amount}));assert.throws(()=>validate('exchangeSwap',{accountId:'a',assetId:'n:native',side:'Sell',amount,slippage:'0.5'}))}for(const side of ['buy','SELL','Limit','',null,1])assert.throws(()=>validate('exchangeQuote',{accountId:'a',assetId:'n:native',side}));for(const slippage of [0,'0','-1','1e-3','1.00000001','1.1','10','0.123456789','0.500000','0.125',null])assert.throws(()=>validate('exchangeSwap',{accountId:'a',assetId:'n:native',side:'Sell',amount:'1',slippage}));
});

test('Exchange requires a complete positive price for Swap while keeping verified deposit routes independent',async t=>{
 const h=await rendererHarness();t.after(h.close);await enterExchange(h);const good=h.handlers.exchangeQuote;
 for(const patch of [{symbol:''},{symbol:'ETHUSDT<script>'},{symbol:1},{lastPrice:null},{lastPrice:1.25},{lastPrice:'0'},{lastPrice:'-1'},{lastPrice:'1e3'},{lastPrice:'01'},{lastPrice:'unavailable'}]){h.handlers.exchangeQuote=body=>({...good(body),...patch});await h.invoke('exchangequote');assert.equal(h.$('exchangeswap').disabled,true);assert.equal(h.$('exchangedeposit').disabled,false);assert.match(h.$('exchangeprice').textContent,/No complete/);await h.invoke('exchangeswap');assert.equal(exchangeMutations(h).length,0)}
 h.handlers.exchangeQuote=body=>({...good(body),route:{supported:false},bidPrice:'',askPrice:''});await h.invoke('exchangequote');assert.match(h.$('exchangeroute').textContent,/no verified route/);assert.match(h.$('exchangeprice').textContent,/bid unknown.*ask unknown/);assert.equal(h.$('exchangedeposit').disabled,true);
 h.handlers.exchangeQuote=body=>({...good(body),route:{supported:true,chain:'ETH',depositEnabled:true,withdrawEnabled:true}});await h.invoke('exchangewithdrawquote');assert.match(h.$('exchangewithdrawroute').textContent,/minimum unknown.*fee unknown/);
 h.handlers.exchangeStatus=()=>({connected:false,configured:true,message:'API permissions unavailable; reconnect in the wallet dialog.',operations:[]});await h.invoke('exchangerefresh');assert.match(h.$('exchangeconnection').textContent,/API permissions unavailable/);
});

test('Exchange operation failures clear prior authority and stale errors cannot alter the next wallet view',async t=>{
 const h=await rendererHarness();t.after(h.close);await enterExchange(h);await h.invoke('exchangequote');h.handlers.exchangeSwap=()=>{throw Error('PRIVATE_EXCHANGE_KEY')};await h.invoke('exchangeswap');assert.equal(h.$('exchangeswap').disabled,true);assert.equal(h.$('exchangedeposit').disabled,true);assert.match(h.$('exchangeresult').textContent,/uncertain outcome/);assert.ok(!h.$('exchangeresult').textContent.includes('PRIVATE'));
 for(const method of ['exchangeQuote','exchangeStatus','exchangeSwap']){await enterExchange(h);await h.invoke('exchangequote');const gate=deferred();h.handlers[method]=()=>gate.promise;const pending=h.invoke(method==='exchangeQuote'?'exchangequote':method==='exchangeStatus'?'exchangerefresh':'exchangeswap');await tick();h.$('viewtabs').children[0].click();gate.reject(Error('PRIVATE_LATE_BYBIT_ERROR'));await pending;assert.equal(h.$('operationerror').hidden,true);assert.equal(h.$('accountoverview').hidden,false);assert.ok(!h.dom.window.document.body.textContent.includes('PRIVATE_LATE'))}
});

test('Exchange preserves hidden account policy and exposes no reconcile control for finalized, malformed or locked operations',async t=>{
 const h=await rendererHarness({accounts:[{id:'a',network:'testnet',index:0,address:'PUBLIC-A'},{id:'hidden',network:'testnet',index:2,address:'PUBLIC-HIDDEN',hidden:true}]});t.after(h.close);await enterExchange(h);assert.deepEqual([...h.$('exchangeaccount').options].map(option=>option.value),['a']);h.$('showhidden').checked=true;h.$('showhidden').onchange();assert.deepEqual([...h.$('exchangeaccount').options].map(option=>option.value),['a','hidden']);h.$('exchangeaccount').value='hidden';h.$('exchangeaccount').onchange();h.$('showhidden').checked=false;h.$('showhidden').onchange();assert.equal(h.$('exchangeaccount').value,'a');const before=h.calls.length;h.notifyLock();for(const id of ['exchangeconnect','exchangedisconnect','exchangequote','exchangewithdrawquote','exchangerefresh','exchangedeposit','exchangeswap','exchangewithdraw'])await h.invoke(id);assert.equal(h.calls.length,before);assert.equal(h.$('exchangeoperations').children.length,0);
});

test('Exchange shows backend route restrictions even for an otherwise supported coin without implying an absolute execution price',async t=>{
 const h=await rendererHarness();t.after(h.close);await enterExchange(h);const good=h.handlers.exchangeQuote,reason='Regional compliance questionnaire is required; this API route is unavailable.';h.handlers.exchangeQuote=body=>({...good(body),route:{supported:true,chain:'ETH',depositEnabled:true,withdrawEnabled:false,reason}});await h.invoke('exchangequote');await h.invoke('exchangewithdrawquote');assert.match(h.$('exchangeroute').textContent,/Regional compliance questionnaire/);assert.match(h.$('exchangewithdrawroute').textContent,/Regional compliance questionnaire/);assert.equal(h.$('exchangedeposit').disabled,false);assert.equal(h.$('exchangewithdraw').disabled,true);assert.match(h.$('exchangeprice').textContent,/relative slippage limit/);assert.ok(!h.$('exchangeprice').textContent.includes('reviewed price limit'));
});

test('Exchange displays public completion reasons, exact fills, fees and remote identities as inert text while dropping private fields',async t=>{
 const h=await rendererHarness();t.after(h.close);await enterExchange(h);await h.invoke('exchangequote');const hostile='<img src=x onerror="globalThis.exfiltrate=true">';h.handlers.exchangeSwap=()=>({id:'original-order',kind:'SPOT',state:'UNKNOWN',message:'Partial execution requires reconciliation. '+hostile,remoteId:'public-bybit-order-id',transactionId:'public-chain-identity',filledBase:'0.123456789012345678',filledQuote:'45.123456',reportedAmount:'0.123456789012345678',reportedFee:'0.000012',fees:{ETH:'0.000000000000000001',USDT:'0.012345',apiSecret:'PRIVATE_NESTED_CANARY',UNKNOWN:'PRIVATE_TEXT_CANARY'},apiKey:'PRIVATE_API_KEY_CANARY',apiSecret:'PRIVATE_API_SECRET_CANARY',raw:{authorization:'PRIVATE_RAW_CANARY'},credentials:{key:'PRIVATE_CREDENTIAL_CANARY'}});await h.invoke('exchangeswap');assert.equal(h.$('exchangedetails').hidden,false);const detail=JSON.parse(h.$('exchangedetails').textContent);assert.equal(detail.message,'Partial execution requires reconciliation. '+hostile);assert.equal(detail.filledBase,'0.123456789012345678');assert.equal(detail.filledQuote,'45.123456');assert.equal(detail.remoteId,'public-bybit-order-id');assert.equal(detail.transactionId,'public-chain-identity');assert.deepEqual(detail.fees,{ETH:'0.000000000000000001',USDT:'0.012345'});assert.equal(h.$('exchangedetails').querySelectorAll('img,script,a').length,0);assert.equal(h.dom.window.exfiltrate,undefined);assert.ok(!h.dom.window.document.body.textContent.includes('PRIVATE_'));assert.match(h.$('exchangeresult').textContent,/UNKNOWN.*Acceptance does not establish/);
 h.notifyLock();assert.equal(h.$('exchangedetails').hidden,true);assert.equal(h.$('exchangedetails').textContent,'Locked');
});

test('Exchange recent operations and reconciled rejection details retain public reasons while stripping unknown and malformed fields',async t=>{
 const h=await rendererHarness();t.after(h.close);await enterExchange(h,{operations:[{id:'original',kind:'WITHDRAW',state:'UNKNOWN',remoteId:'public-remote-id',message:'<script>inert</script>',amount:'1.00000001',apiKey:'PRIVATE_OPERATION_KEY',credentials:{apiSecret:'PRIVATE_OPERATION_SECRET'}}]});assert.ok(!h.$('exchangeoperations').textContent.includes('PRIVATE_'));assert.match(h.$('exchangeoperations').textContent,/public-remote-id/);assert.equal(h.$('exchangeoperations').querySelectorAll('script').length,0);h.handlers.exchangeReconcile=()=>({id:'original',state:'FAILED',message:'Withdrawal rejected: the selected region requires a beneficiary questionnaire.',remoteId:'public-remote-id',filledBase:1,filledQuote:{secret:'PRIVATE_BAD_FILLED'},reportedAmount:'1.00000001',fees:{USDT:'0.1',A:null,B:1,C:'-1',D:'1e3',E:'',F:'1'.repeat(129),'bad-key':'0.2'},apiSecret:'PRIVATE_RECONCILE_SECRET'});await h.$('exchangeoperations').querySelector('button').onclick();const detail=JSON.parse(h.$('exchangedetails').textContent);assert.equal(detail.state,'FAILED');assert.match(detail.message,/beneficiary questionnaire/);assert.equal(detail.reportedAmount,'1.00000001');assert.deepEqual(detail.fees,{USDT:'0.1'});assert.equal(Object.hasOwn(detail,'filledBase'),false);assert.equal(Object.hasOwn(detail,'filledQuote'),false);assert.ok(!h.dom.window.document.body.textContent.includes('PRIVATE_'));
});

test('Exchange clears prior public details before another request and never reflects unsupported result shapes or oversized fields',async t=>{
 const h=await rendererHarness();t.after(h.close);await enterExchange(h);for(const value of [null,1,'PRIVATE_RESPONSE_STRING',{apiSecret:'PRIVATE_UNSUPPORTED',message:'x'.repeat(4097),fees:[]},{fees:{USDT:null}}]){await h.invoke('exchangequote');h.handlers.exchangeSwap=()=>value;await h.invoke('exchangeswap');assert.equal(h.$('exchangedetails').hidden,true);assert.ok(!h.dom.window.document.body.textContent.includes('PRIVATE_'))}
 await h.invoke('exchangequote');h.handlers.exchangeSwap=()=>({state:'SUBMITTED',remoteId:'public-reference'});await h.invoke('exchangeswap');assert.equal(h.$('exchangedetails').hidden,false);await h.invoke('exchangequote');const gate=deferred();h.handlers.exchangeSwap=()=>gate.promise;const pending=h.invoke('exchangeswap');await tick();assert.equal(h.$('exchangedetails').hidden,true);assert.equal(h.$('exchangedetails').textContent,'');h.notifyLock();gate.resolve({state:'FILLED',remoteId:'LATE-EXCHANGE-DETAIL'});await pending;assert.equal(h.$('exchangedetails').hidden,true);assert.equal(h.$('exchangedetails').textContent,'Locked');assert.ok(!h.dom.window.document.body.textContent.includes('LATE-EXCHANGE-DETAIL'));
});

test('Exchange restores a truthful empty operation state after unlocking a previously locked renderer',async t=>{
 const h=await rendererHarness({state:{locked:true}});t.after(h.close);assert.equal(h.$('exchangeresult').textContent,'Locked');h.setState({accounts:[{id:'a',network:'testnet',index:0,address:'PUBLIC-A'}]});await h.invoke('unlock');await enterExchange(h,{connected:false});assert.equal(h.$('exchangeresult').textContent,'No exchange action requested.');assert.equal(h.$('exchangedetails').hidden,true);for(const id of ['exchangedeposit','exchangeswap','exchangewithdraw'])assert.equal(h.$(id).disabled,true);
});
